effect.shader:
vec4 u_xlat0;
vec4 u_xlat1;
bool u_xlatb1;
vec3 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec3 u_xlat7;
bool u_xlatb7;
void main()
{
    u_xlat0 = texture(inputImg, acScreenNorm.xy);
    u_xlat1.x = _relief * 0.00100000005;
    u_xlatb7 = int(_invert)==1;
    if(u_xlatb7){
        u_xlat7.xyz = max(u_xlat0.xyz, vec3(0.0, 0.0, 0.0));
        u_xlat7.xyz = log2(u_xlat7.xyz);
        u_xlat7.xyz = u_xlat7.xyz * vec3(0.416666657, 0.416666657, 0.416666657);
        u_xlat7.xyz = exp2(u_xlat7.xyz);
        u_xlat7.xyz = u_xlat7.xyz * vec3(1.05499995, 1.05499995, 1.05499995) + vec3(-0.0549999997, -0.0549999997, -0.0549999997);
        u_xlat7.xyz = max(u_xlat7.xyz, vec3(0.0, 0.0, 0.0));
        u_xlat2.x = _direction * 0.0174532924;
        u_xlat3.x = cos(u_xlat2.x);
        u_xlat2.x = sin(u_xlat2.x);
        u_xlat3.y = u_xlat2.x;
        u_xlat2.xy = u_xlat3.xy * u_xlat1.xx + acScreenNorm.xy;
        u_xlat2.xyz = texture(inputImg, u_xlat2.xy).xyz;
        u_xlat2.xyz = max(u_xlat2.xyz, vec3(0.0, 0.0, 0.0));
        u_xlat2.xyz = log2(u_xlat2.xyz);
        u_xlat2.xyz = u_xlat2.xyz * vec3(0.416666657, 0.416666657, 0.416666657);
        u_xlat2.xyz = exp2(u_xlat2.xyz);
        u_xlat2.xyz = u_xlat2.xyz * vec3(1.05499995, 1.05499995, 1.05499995) + vec3(-0.0549999997, -0.0549999997, -0.0549999997);
        u_xlat2.xyz = max(u_xlat2.xyz, vec3(0.0, 0.0, 0.0));
        u_xlat7.xyz = u_xlat7.xyz + (-u_xlat2.xyz);
        u_xlat7.xyz = u_xlat7.xyz * vec3(vec3(_contrast, _contrast, _contrast)) + vec3(0.5, 0.5, 0.5);
    } else {
        u_xlat2.x = _direction * 0.0174532924;
        u_xlat3.x = cos(u_xlat2.x);
        u_xlat2.x = sin(u_xlat2.x);
        u_xlat3.y = u_xlat2.x;
        u_xlat2.xy = u_xlat3.xy * u_xlat1.xx + acScreenNorm.xy;
        u_xlat2.xyz = texture(inputImg, u_xlat2.xy).xyz;
        u_xlat2.xyz = max(u_xlat2.xyz, vec3(0.0, 0.0, 0.0));
        u_xlat2.xyz = log2(u_xlat2.xyz);
        u_xlat2.xyz = u_xlat2.xyz * vec3(0.416666657, 0.416666657, 0.416666657);
        u_xlat2.xyz = exp2(u_xlat2.xyz);
        u_xlat2.xyz = u_xlat2.xyz * vec3(1.05499995, 1.05499995, 1.05499995) + vec3(-0.0549999997, -0.0549999997, -0.0549999997);
        u_xlat2.xyz = max(u_xlat2.xyz, vec3(0.0, 0.0, 0.0));
        u_xlat3.xyz = max(u_xlat0.xyz, vec3(0.0, 0.0, 0.0));
        u_xlat3.xyz = log2(u_xlat3.xyz);
        u_xlat3.xyz = u_xlat3.xyz * vec3(0.416666657, 0.416666657, 0.416666657);
        u_xlat3.xyz = exp2(u_xlat3.xyz);
        u_xlat3.xyz = u_xlat3.xyz * vec3(1.05499995, 1.05499995, 1.05499995) + vec3(-0.0549999997, -0.0549999997, -0.0549999997);
        u_xlat3.xyz = max(u_xlat3.xyz, vec3(0.0, 0.0, 0.0));
        u_xlat2.xyz = u_xlat2.xyz + (-u_xlat3.xyz);
        u_xlat7.xyz = u_xlat2.xyz * vec3(vec3(_contrast, _contrast, _contrast)) + vec3(0.5, 0.5, 0.5);
    }
    u_xlatb1 = int(_bw)==1;
    u_xlat2.x = u_xlat7.y + u_xlat7.x;
    u_xlat2.x = u_xlat7.z + u_xlat2.x;
    u_xlat2.x = u_xlat2.x * 0.333333343;
    u_xlat1.xyz = (bool(u_xlatb1)) ? u_xlat2.xxx : u_xlat7.xyz;
    u_xlat2.xyz = u_xlat1.xyz * vec3(0.305306017, 0.305306017, 0.305306017) + vec3(0.682171106, 0.682171106, 0.682171106);
    u_xlat2.xyz = u_xlat1.xyz * u_xlat2.xyz + vec3(0.0125228781, 0.0125228781, 0.0125228781);
    u_xlat1.xyz = u_xlat1.xyz * u_xlat2.xyz;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat1.w = u_xlat0.w;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat5 = u_xlat0 * u_xlat5;
        u_xlat3 = u_xlat3 * u_xlat4 + u_xlat5;
        u_xlat0.x = u_xlat4.x * u_xlat3.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat0.x : u_xlat3.w;
        fragColor.xyz = u_xlat3.xyz;
    } else {
        fragColor.xyz = u_xlat1.xyz;
        fragColor.w = u_xlat0.w;
    }
    return;
}
